   338	// createCheckpointOnMetadataBranchFull creates a checkpoint on the entire/checkpoints/v1 branch
   339	// with a caller-specified checkpoint ID and timestamp.
   340	func createCheckpointOnMetadataBranchFull(t *testing.T, repo *git.Repository, sessionID string, checkpointID id.CheckpointID, createdAt time.Time) id.CheckpointID {
   341		t.Helper()
   342	
   343		// Get existing metadata branch or create it
   344		if err := strategy.EnsureMetadataBranch(repo); err != nil {
   345			t.Fatalf("Failed to ensure metadata branch: %v", err)
   346		}
   347	
   348		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   349		ref, err := repo.Reference(refName, true)
   350		if err != nil {
   351			t.Fatalf("Failed to get metadata branch ref: %v", err)
   352		}
   353	
   354		parentCommit, err := repo.CommitObject(ref.Hash())
   355		if err != nil {
   356			t.Fatalf("Failed to get parent commit: %v", err)
   357		}
   358	
   359		// Create metadata content
   360		metadataJSON := fmt.Sprintf(`{
   361	  "checkpoint_id": %q,
   362	  "session_id": %q,
   363	  "created_at": %q,
   364	  "agent": %q
   365	}`, checkpointID.String(), sessionID, createdAt.Format(time.RFC3339), agent.AgentTypeClaudeCode)
   366	
   367		// Create blob for metadata
   368		blob := repo.Storer.NewEncodedObject()
   369		blob.SetType(plumbing.BlobObject)
   370		writer, err := blob.Writer()
   371		if err != nil {
   372			t.Fatalf("Failed to create blob writer: %v", err)
   373		}
   374		if _, err := writer.Write([]byte(metadataJSON)); err != nil {
   375			t.Fatalf("Failed to write blob: %v", err)
   376		}
   377		if err := writer.Close(); err != nil {
   378			t.Fatalf("Failed to close writer: %v", err)
   379		}
   380		metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
   381		if err != nil {
   382			t.Fatalf("Failed to store blob: %v", err)
   383		}
   384	
   385		// Create session log blob
   386		logBlob := repo.Storer.NewEncodedObject()
   387		logBlob.SetType(plumbing.BlobObject)
   388		logWriter, err := logBlob.Writer()
   389		if err != nil {
   390			t.Fatalf("Failed to create log blob writer: %v", err)
   391		}
   392		if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
   393			t.Fatalf("Failed to write log blob: %v", err)
   394		}
   395		if err := logWriter.Close(); err != nil {
   396			t.Fatalf("Failed to close log writer: %v", err)
   397		}
   398		logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
   399		if err != nil {
   400			t.Fatalf("Failed to store log blob: %v", err)
   401		}
   402	
   403		// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
   404		shardedPath := checkpointID.Path()
   405		checkpointIDStr := checkpointID.String()
   406	
   407		// Create checkpoint tree with metadata and transcript files
   408		// Entries must be sorted alphabetically
   409		checkpointTree := object.Tree{
   410			Entries: []object.TreeEntry{
   411				{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
   412				{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
   413			},
   414		}
   415		checkpointTreeObj := repo.Storer.NewEncodedObject()
   416		if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
   417			t.Fatalf("Failed to encode checkpoint tree: %v", err)
   418		}
   419		checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
   420		if err != nil {
   421			t.Fatalf("Failed to store checkpoint tree: %v", err)
   422		}
   423	
   424		// Create inner shard tree (id[2:])
   425		innerTree := object.Tree{
   426			Entries: []object.TreeEntry{
   427				{Name: checkpointIDStr[2:], Mode: filemode.Dir, Hash: checkpointTreeHash},
   428			},
   429		}
   430		innerTreeObj := repo.Storer.NewEncodedObject()
   431		if err := innerTree.Encode(innerTreeObj); err != nil {
   432			t.Fatalf("Failed to encode inner tree: %v", err)
   433		}
   434		innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
   435		if err != nil {
   436			t.Fatalf("Failed to store inner tree: %v", err)
   437		}
   438	
   439		// Get existing tree entries from parent
   440		parentTree, err := parentCommit.Tree()
   441		if err != nil {
   442			t.Fatalf("Failed to get parent tree: %v", err)
   443		}
   444	
   445		// Build new root tree with shard bucket
   446		var rootEntries []object.TreeEntry
   447		for _, entry := range parentTree.Entries {
   448			if entry.Name != shardedPath[:2] {
   449				rootEntries = append(rootEntries, entry)
   450			}
   451		}
   452		rootEntries = append(rootEntries, object.TreeEntry{
   453			Name: checkpointIDStr[:2],
   454			Mode: filemode.Dir,
   455			Hash: innerTreeHash,
   456		})
   457	
   458		rootTree := object.Tree{Entries: rootEntries}
   459		rootTreeObj := repo.Storer.NewEncodedObject()
   460		if err := rootTree.Encode(rootTreeObj); err != nil {
   461			t.Fatalf("Failed to encode root tree: %v", err)
   462		}
   463		rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
   464		if err != nil {
   465			t.Fatalf("Failed to store root tree: %v", err)
   466		}
   467	
   468		// Create commit on metadata branch
   469		commit := &object.Commit{
   470			Author: object.Signature{
   471				Name:  "Test",
   472				Email: "test@example.com",
   473				When:  parentCommit.Author.When,
   474			},
   475			Committer: object.Signature{
   476				Name:  "Test",
   477				Email: "test@example.com",
   478				When:  parentCommit.Author.When,
   479			},
   480			Message:      "Add checkpoint metadata",
   481			TreeHash:     rootTreeHash,
   482			ParentHashes: []plumbing.Hash{parentCommit.Hash},
   483		}
   484		commitObj := repo.Storer.NewEncodedObject()
   485		if err := commit.Encode(commitObj); err != nil {
   486			t.Fatalf("Failed to encode commit: %v", err)
   487		}
   488		commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   489		if err != nil {
   490			t.Fatalf("Failed to store commit: %v", err)
   491		}
   492	
   493		// Update metadata branch ref
   494		newRef := plumbing.NewHashReference(refName, commitHash)
   495		if err := repo.Storer.SetReference(newRef); err != nil {
   496			t.Fatalf("Failed to update metadata branch: %v", err)
   497		}
   498	
   499		return checkpointID
   500	}
