  1191	// makeLocalMetadataBranchStale advances origin/entire/checkpoints/v1 to the
  1192	// current local hash and rewinds the local ref back to baseHash, leaving the
  1193	// local metadata branch behind its remote-tracking counterpart. Returns the
  1194	// hash the remote-tracking ref now points at.
  1195	func makeLocalMetadataBranchStale(t *testing.T, repo *git.Repository, baseHash plumbing.Hash) plumbing.Hash {
  1196		t.Helper()
  1197		localRefName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1198		current, err := repo.Reference(localRefName, true)
  1199		if err != nil {
  1200			t.Fatalf("read advanced metadata branch ref: %v", err)
  1201		}
  1202		if current.Hash() == baseHash {
  1203			t.Fatalf("makeLocalMetadataBranchStale: local ref must have advanced past baseHash before calling")
  1204		}
  1205		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
  1206		if err := repo.Storer.SetReference(plumbing.NewHashReference(remoteRefName, current.Hash())); err != nil {
  1207			t.Fatalf("set remote-tracking ref: %v", err)
  1208		}
  1209		if err := repo.Storer.SetReference(plumbing.NewHashReference(localRefName, baseHash)); err != nil {
  1210			t.Fatalf("rewind local metadata branch: %v", err)
  1211		}
  1212		return current.Hash()
  1213	}
