  1329	// splitLines splits content into lines, preserving empty lines.
  1330	// Handles both Unix (\n) and Windows (\r\n) line endings.
  1331	func splitLines(content []byte) []string {
  1332		if len(content) == 0 {
  1333			return nil
  1334		}
  1335		s := string(content)
  1336		// Normalize Windows line endings to Unix
  1337		s = strings.ReplaceAll(s, "\r\n", "\n")
  1338		// Remove trailing newline to avoid empty last element
  1339		s = strings.TrimSuffix(s, "\n")
  1340		return strings.Split(s, "\n")
  1341	}
