  1443	// DeleteBranchCLI deletes a git branch using the git CLI.
  1444	// Uses `git branch -D` instead of go-git's RemoveReference because go-git v5
  1445	// doesn't properly persist deletions when refs are packed (.git/packed-refs)
  1446	// or in a worktree context. This is the same class of go-git v5 bug that
  1447	// affects checkout and reset --hard (see HardResetWithProtection).
  1448	//
  1449	// Returns ErrBranchNotFound if the branch does not exist, allowing callers
  1450	// to use errors.Is for idempotent deletion patterns.
  1451	func DeleteBranchCLI(ctx context.Context, branchName string) error {
  1452		// Pre-check: verify the branch exists so callers get a structured error
  1453		// instead of parsing git's output string (which varies across locales).
  1454		// git show-ref exits 1 for "not found" and 128+ for fatal errors (corrupt
  1455		// repo, permissions, not a git directory). Only map exit code 1 to
  1456		// ErrBranchNotFound; propagate other failures as-is.
  1457		check := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName)
  1458		if err := check.Run(); err != nil {
  1459			var exitErr *exec.ExitError
  1460			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
  1461				return fmt.Errorf("%w: %s", ErrBranchNotFound, branchName)
  1462			}
  1463			return fmt.Errorf("failed to check branch %s: %w", branchName, err)
  1464		}
  1465	
  1466		cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", branchName)
  1467		if output, err := cmd.CombinedOutput(); err != nil {
  1468			return fmt.Errorf("failed to delete branch %s: %s: %w", branchName, strings.TrimSpace(string(output)), err)
  1469		}
  1470		return nil
  1471	}
