func readCheckpointInfoFromStore(ctx context.Context, store *checkpoint.GitStore, checkpointID id.CheckpointID) (*strategy.CheckpointInfo, error) {
	summary, err := checkpoint.ReadCommittedCheckpoint(ctx, store, checkpointID)
	if err != nil {
		return readCheckpointInfoFromCommittedRef(ctx, store, checkpointID, fmt.Errorf("read checkpoint: %w", err))
	}
	info := &strategy.CheckpointInfo{
		CheckpointID:     checkpointID,
		CheckpointsCount: summary.CheckpointsCount,
		FilesTouched:     summary.FilesTouched,
		SessionCount:     len(summary.Sessions),
	}
	for i := range summary.Sessions {
		metadata, metaErr := store.ReadSessionMetadata(ctx, checkpointID, i)
		if metaErr != nil {
			logging.Debug(ctx, "read checkpoint metadata: session metadata read failed",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.Int("session_index", i),
				slog.String("error", metaErr.Error()),
			)
			continue
		}
		info.SessionIDs = append(info.SessionIDs, metadata.SessionID)
		if metadata.SessionID != "" {
			info.SessionID = metadata.SessionID
			info.CreatedAt = metadata.CreatedAt
			info.Agent = metadata.Agent
			info.IsTask = metadata.IsTask
			info.ToolUseID = metadata.ToolUseID
		}
	}
	if info.SessionID == "" {
		return readCheckpointInfoFromCommittedRef(ctx, store, checkpointID, checkpoint.ErrCheckpointNotFound)
	}
	return info, nil
}

func readCheckpointInfoFromCommittedRef(
	ctx context.Context,
	store *checkpoint.GitStore,
	checkpointID id.CheckpointID,
	storeErr error,
) (*strategy.CheckpointInfo, error) {
	tree, err := getCommittedReadTree(store.Repository(), store.CommittedReadRef())
	if err != nil {
		return nil, errors.Join(storeErr, err)
	}

	cpSubtree, err := tree.Tree(checkpointID.Path())
	if err != nil {
		return nil, errors.Join(storeErr, fmt.Errorf("find checkpoint subtree: %w", err))
	}

	ft := checkpoint.NewFetchingTree(ctx, cpSubtree, store.Repository().Storer, FetchBlobsByHash)
	info, err := strategy.ReadCheckpointMetadataFromSubtree(ft, checkpointID.Path())
	if err != nil {
		return nil, errors.Join(storeErr, fmt.Errorf("read checkpoint metadata: %w", err))
	}
	if info.SessionID == "" {
		return nil, errors.Join(storeErr, checkpoint.ErrCheckpointNotFound)
	}
	return info, nil
}

func getCommittedReadTree(repo *git.Repository, committedReadRef plumbing.ReferenceName) (*object.Tree, error) {
	ref, err := repo.Reference(committedReadRef, true)
	if err != nil {
		if committedReadRef != plumbing.NewBranchReferenceName(paths.MetadataBranchName) {
			return nil, fmt.Errorf("committed read ref %s not found: %w", committedReadRef, err)
		}
		remoteRef := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
		ref, err = repo.Reference(remoteRef, true)
		if err != nil {
			return nil, fmt.Errorf("committed read ref %s not found: %w", committedReadRef, err)
		}
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get committed read commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get committed read tree: %w", err)
	}
	return tree, nil
}

